function dir$ss_bctkdh(p){
  this.constructor(p);
}
dir$ss_bctkdh.prototype = new DirEvent();
dir$ss_bctkdh.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
  document._dir = this._dir;
}
dir$ss_bctkdh.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid(0);
  var exp = {
    //tong_trong: ['*tong_trong', '[so_luong]*[ty_trong]'],
	//tong_khoi: ['*tong_khoi', '[so_luong]*[ty_khoi]'],

    t_so_luong: ['@t_so_luong', '[so_luong]'],
	t_tong_trong: ['@t_tong_trong', '[tong_trong]'],
	t_tong_khoi: ['@t_tong_khoi', '[tong_khoi]'],
  }
  p.applyExpression(exp, g, false);

  g.FomulaApplied = {
	"!ty_gia":[],
    "so_luong":["t_so_luong", "tong_trong", "tong_khoi","t_tong_trong", "t_tong_khoi"],
    "ty_trong":["tong_trong","t_so_luong", "t_tong_trong"],
	"ty_khoi":["tong_khoi","t_so_luong", "t_tong_khoi"],
	"tong_trong":["t_tong_trong"],
	"tong_khoi":["t_tong_khoi"],
  }
  //console.log(JSON.stringify(g.FomulaApplied)); //Gan la ds cong thuc tinh cho cot nao do: 


  p.options.FCColumns = {FC: [], BC: []};
  g.FCColumns = {FC: [], BC: []};

  var oldTG = '', oTG = p.jObject('ma_nt'); //Neu ty gia thay doi
  oTG.focus(function(){ oldTG = oTG.fval(); }).blur(function(){ if (oldTG != oTG.fval()) onExRateChanged(oTG, p);});
  p.applyFCColumns();
  p.applyFCColumns(g);
 // p.setFCHidden(oTG.fval());

  dir$ss_bctkdhDisabledMasterField(p, g);
  dir$ss_bctkdhHiddenColumnByType(p);
  dir$ss_bctkdhHiddenColumnByTran(p)
  dir$ss_bctkdhDisabledMasterPort(p);
  dir$ss_bctkdhDisabledStatusByAction(p);
  dir$ss_bctkdhLoadDataQuote(p);
  dir$ss_bctkdhLoadDataJob(p);
  dir$ss_bctkdhGetSalesEmployee(p);
}

