dir$ss_bctkdh.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$ss_bctkdhDisabledMasterField(p, p.grid(gindex));
