function dir$ss_bctkdhDisabledMasterPort(p){

}
function dir$ss_bctkdhDisabledMasterField(p, g){
	if (p.options.action == "NEW")
	{
		p.setDisabled(['ma_nt', 'so_job','so_ct'], true);
	}
	else {
		p.setDisabled(['unit_id', 'ma_ngv', 'ngay_ct', 'ma_job', 'so_job', 'so_ct'], true);
	}

}
function dir$ss_bctkdhHiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
  var date = new Date();
  if(p.options.action == 'NEW') {
	if(v ==1) {
		p.setInvisible('tt', true);
		p.valForm('ma_kh', "" , true);
		p.valForm('ma_hang', "" , true);
		p.valForm('ma_noi_di', "" , true);
		p.valForm('ma_noi_den', "" , true);
		p.valForm('ma_nv', "" , true);
		p.valForm('id_tg', "" , true);
		p.valForm('ds_cong',"",true);
		p.valForm('ngay_hl',date,true);
		p.valForm('ngay_hld',"",true);
		p.valForm('t_so_luong',"",true);
		p.clearGrid(0);

		return;
	}if(v == 2) {
		p.setInvisible('tt', false);
		p.valForm('ma_kh', "" , true);
		p.valForm('ma_hang', "" , true);
		p.valForm('ma_noi_di', "" , true);
		p.valForm('ma_noi_den', "" , true);
		p.valForm('ma_nv', "" , true);
		p.valForm('id_bg', "" , true);
		p.valForm('ds_cong',"",true);
		p.valForm('ngay_hl',date,true);
		p.valForm('ngay_hld',"",true);
		p.valForm('t_so_luong',"",true);
		p.clearGrid(0);


		return;
	}
  }
}
function dir$ss_bctkdhGetSalesEmployee(p){
	var makh = p.valForm('ma_kh');
	if ( makh != "" ) p.request('get_EmployeeSales', '',['ma_kh'])
	else p.valForm('ma_nv',"",true);
}
function dir$ss_bctkdhLoadDataJob(p){
	var majob = p.valForm('ma_job');
	if(p.options.action == "NEW") {

		if ( majob != "" ) p.request('so_job', '',['ngay_ct','ma_job'])
		else p.valForm('so_job',"",true);
	}
}
function dir$ss_bctkdhLoadDataQuote(p){
	if (p.options.action != "NEW" ) {

		p.request('get_tongtien', '', 'id')

	}
}
function dir$ss_bctkdhHiddenColumnByTran(p){
    if (p.options.action == 'NEW') p.valForm('ma_job',"",true);

}
function dir$ss_bctkdhDisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=6],[value=7],[value=9]").remove();
}








