        &VoucherNumberBeforeSave;

		if @@admin = 0 and @status = 7 and not exists(select 1 from kbnguoiduyet y where y.user_id = @@userId and y.status = 1 and y.loai = 1 and @ma_nt = y.ma_nt and (y.tien = 0 or @t_tt_nt <= y.tien)) begin
		  select '$notApproveRight' as message, 'status' as field
		  return
		end
		declare @i_so_job varchar(32), @ES int, @m VARCHAR(15), @px varchar(12);

		SELECT @px = substring(REPLACE(CONVERT(VARCHAR, @ngay_ct),'-',''),3,4)

		if exists (select 1 from @@table where so_job = @so_job and ma_job = @ma_job and LEFT(CONVERT(VARCHAR( 6), ngay_ct, 12),4) = @px ) BEGIN
			SELECT @m = MAX(so_job) FROM @@table WHERE so_job LIKE @px + '%' and ma_job = @ma_job and LEFT(CONVERT(VARCHAR( 6), ngay_ct, 12),4) = @px
			SET @m = REPLACE(@m, @px, '')
			SELECT @i_so_job = @px + RIGHT('000' + CAST(CAST(@m AS INT) + 1 AS VARCHAR(3)), 4)
			SET @ES = 1
		end

		if @ES = 1 begin

			select @so_job = @i_so_job , @warning = '$NumberVoucherExists'

		end






